  const redraw = () => guiADUC(el, L, d, done); if (!L.ad) { el.innerHTML = '<div class="gui"><p class="bad">Naming information cannot be located because: The specified domain either does not exist or could not be contacted.</p></div>'; return; }
  const A = L.ad, base = A.domain.split('.').map((x) => `DC=${x}`).join(','); const run = (cmd) => { st.res = winPs(L, d, cmd); settle(L, 'nodhcp'); done(); redraw(); };
