  const objs = [...Object.entries(A.users).filter(([, u]) => u.ou === st.ou).map(([k, u]) => ({ k, type: 'User', name: u.name || k, desc: u.desc || '', dis: u.enabled === false, lock: u.locked })), ...Object.entries(A.groups).filter(([, g]) => g.ou === st.ou).map(([k, g]) => ({ k, type: `Security Group - ${g.scope}`, name: k, desc: '' })), ...Object.entries(A.computers).filter(([, c]) => c.ou === st.ou).map(([k, c]) => ({ k, type: 'Computer', name: k, desc: c.os || '', dis: c.enabled === false }))];
