    if (st.v === 'pool') pane += `<table><tr><th>Start IP</th><th>End IP</th><th>Description</th></tr><tr><td>${esc(s.start)}</td><td>${esc(s.end)}</td><td>Address range for distribution</td></tr>${(s.excl || []).map(([a, b]) => `<tr><td>${esc(a)}</td><td>${esc(b)}</td><td>IP Addresses excluded from distribution</td></tr>`).join('')}</table><div class="fm"><label>New exclusion: start</label><input id="xS"><label>end</label><input id="xE"></div><button class="btn sm" id="xOk">Add exclusion</button><div class="fm"><label>Change range: start</label><input id="rS" value="${esc(s.start)}"><label>end</label><input id="rE" value="${esc(s.end)}"></div><button class="btn sm" id="rOk">Apply range</button>`;
