    if (v('#eCp')) out.push(winPs(L, d, `Set-GPRegistryValue -Name ${psq(st.g)} -Key ${psq(key('Explorer'))} -ValueName NoControlPanel -Type DWord -Value 1`).text || 'Control Panel prohibited');
    if (v('#eUsb')) out.push(winPs(L, d, `Set-GPRegistryValue -Name ${psq(st.g)} -Key 'HKLM\\Software\\Policies\\Microsoft\\Windows\\RemovableStorageDevices' -ValueName Deny_All -Type DWord -Value 1`).text || 'Removable storage denied');
    if (v('#eFw')) { G.comp.fw = true; G.ver = (G.ver || 1) + 1; out.push('Firewall enforced'); }
