// ---------------------------------------------------------------- Windows Setup (a server booted from the ISO)
/** What Setup leaves behind: a fresh server with a random name, DHCP, default roles */
function winInstall(L, d, ed, pass) {
  Object.assign(d, { setup: null, server: true, ver: `Microsoft ${ed.replace(' (Desktop Experience)', '')}`, core: !/Desktop/.test(ed), adminPass: pass, hostname: `WIN-${(d.id.split('').reduce((s, c) => s * 31 + c.charCodeAt(0), 7) >>> 0).toString(36).toUpperCase().slice(0, 11).padEnd(11, 'Q')}` }); d.name = d.hostname;
  d._win = false; delete d.svc; delete d.features; delete d.events; delete d.updates; winInit(L, d); d.localPass = { Administrator: pass };
  Object.values(d.nics).forEach((c) => Object.assign(c, { up: true, tried: false, ip: c.dhcp ? null : c.ip }));
  L.cmdlog.push({ dev: d.id, kind: 'setup', line: `installed ${ed}`, t: L.clock }); settle(L);
}
