  if (st.step === 3) h = scr('Installing Windows', '<p>✔ Copying Windows files<br>✔ Getting files ready for installation (100%)<br>✔ Installing features<br>✔ Installing updates<br>✔ Finishing up</p><p class="m">Windows needs to restart to continue.</p>', '<button class="btn p" id="n">Restart now</button>');
  if (st.step === 4) h = scr('Customize settings', '<p>Type a password for the built-in administrator account that you can use to sign in to this computer.</p><div class="grid2"><label class="f">User name<input value="Administrator" disabled></label><span></span><label class="f">Password<input id="p1" type="password"></label><label class="f">Reenter password<input id="p2" type="password"></label></div><div id="pe"></div>', '<button class="btn p" id="n">Finish</button>');
  el.innerHTML = h;
